245	diff --git a/lib/features/export/data/datasources/export_remote_data_source.dart b/lib/features/export/data/datasources/export_remote_data_source.dart
246	new file mode 100644
247	index 0000000..0c91415
248	--- /dev/null
249	+++ b/lib/features/export/data/datasources/export_remote_data_source.dart
250	@@ -0,0 +1,55 @@
251	+import 'package:fpdart/fpdart.dart';
252	+
253	+import '../../../../core/failure/failure.dart';
254	+import '../../../../core/network/api_client.dart';
255	+import '../models/export_job_status_dto.dart';
256	+
257	+/// The export feature's one remote data source — `export-summary-create`/
258	+/// `export-status-get`, called by `x-cerne-function` name only
259	+/// (AGENTS.md), [jobId] appended as [getStatus]'s one trailing path
260	+/// segment. Mirrors `ChatRemoteDataSource`'s own try/catch-to-
261	+/// `malformedResponse` shape for every decode step (RNF09).
262	+class ExportRemoteDataSource {
263	+  ExportRemoteDataSource(this._apiClient);
264	+
265	+  final ApiClient _apiClient;
266	+
267	+  /// `includeNarrative` is left unset — its own `openapi.yaml` default is
268	+  /// `true`, and docs/input gives this story no reason to ever request a
269	+  /// narrative-less export.
270	+  Future<Either<Failure, String>> createJob({
271	+    required DateTime periodStart,
272	+    required DateTime periodEnd,
273	+  }) async {
274	+    final result = await _apiClient.post(
275	+      'export-summary-create',
276	+      data: {
277	+        'periodStart': periodStart.toUtc().toIso8601String(),
278	+        'periodEnd': periodEnd.toUtc().toIso8601String(),
279	+      },
280	+    );
281	+    return result.flatMap((json) {
282	+      try {
283	+        final data = json['data'] as Map<String, dynamic>;
284	+        return right(data['jobId'] as String);
285	+      } catch (error) {
286	+        return left(Failure.malformedResponse(message: error.toString()));
287	+      }
288	+    });
289	+  }
290	+
291	+  Future<Either<Failure, ExportJobStatusDto>> getStatus(String jobId) async {
292	+    final result = await _apiClient.get(
293	+      'export-status-get',
294	+      pathParams: [jobId],
295	+    );
296	+    return result.flatMap((json) {
297	+      try {
298	+        final data = json['data'] as Map<String, dynamic>;
299	+        return right(ExportJobStatusDto.fromJson(data));
300	+      } catch (error) {
301	+        return left(Failure.malformedResponse(message: error.toString()));
302	+      }
303	+    });
304	+  }
305	+}
