311	@@ -0,0 +1,86 @@
312	+import 'package:json_annotation/json_annotation.dart';
313	+
314	+import '../../../../core/failure/failure.dart';
315	+import '../../domain/entities/export_job_state.dart';
316	+
317	+part 'export_job_status_dto.g.dart';
318	+
319	+/// `export.status.get`'s own response `data` (`openapi.yaml:1495-1539`) —
320	+/// decodes every field the contract declares, even [narrativeErrorCode]/
321	+/// [downloadAvailable] which this story never reads (both belong to
322	+/// Story 7.2's download wiring) — kept here so the DTO always mirrors the
323	+/// full contract shape, not just today's consumer.
324	+@JsonSerializable()
325	+class ExportJobStatusDto {
326	+  const ExportJobStatusDto({
327	+    required this.jobId,
328	+    required this.status,
329	+    required this.narrativeStatus,
330	+    required this.entryCount,
331	+    required this.errorCode,
332	+    required this.narrativeErrorCode,
333	+    required this.downloadAvailable,
334	+  });
335	+
336	+  final String jobId;
337	+  final String status;
338	+  final String narrativeStatus;
339	+  final int? entryCount;
340	+  final String? errorCode;
341	+  final String? narrativeErrorCode;
342	+  final bool downloadAvailable;
343	+
344	+  factory ExportJobStatusDto.fromJson(Map<String, dynamic> json) =>
345	+      _$ExportJobStatusDtoFromJson(json);
346	+
347	+  Map<String, dynamic> toJson() => _$ExportJobStatusDtoToJson(this);
348	+
349	+  /// `docs/input/backend/export-screen-states.md`'s own status×
350	+  /// narrativeStatus×downloadAvailable mapping table, implemented once
351	+  /// here — `ExportRepositoryImpl.getStatus`'s own "thin pass-through"
352	+  /// (Code Map) calls straight through to this method, with no mapping
353	+  /// logic of its own.
354	+  ///
355	+  /// AD-3 ("reuse the existing `Failure.exportEmptyPeriod`... never add a
356	+  /// new `Failure` subtype") is honored by going through the one shared
357	+  /// [Failure.fromCode] for every `status: 'error'` response and then
358	+  /// branching on the *subtype* it returns, rather than re-testing the
359	+  /// literal `'EXPORT_EMPTY_PERIOD'` string a second time here — this
360	+  /// stays correct even if a future taxonomy edit ever changed which code
361	+  /// means "empty period", with no second place to update.
362	+  ExportJobState toState() {
363	+    switch (status) {
364	+      case 'pending':
365	+        return const ExportJobState.preparing();
366	+      case 'processing':
367	+      case 'data_ready':
368	+        // Design Notes — `data_ready` folds into `generating`'s own
369	+        // visual here, no case of its own (lighting it up is Story
370	+        // 7.2's job).
371	+        return const ExportJobState.generating();
372	+      case 'done':
373	+        return ExportJobState.done(
374	+          narrativeStatus == 'done'
375	+              ? ExportOutcome.narrativeReady
376	+              : ExportOutcome.narrativeUnavailable,
377	+        );
378	+      case 'error':
379	+        final failure = Failure.fromCode(
380	+          errorCode ?? '',
381	+          'Não foi possível gerar a exportação.',
382	+        );
383	+        return failure is ExportEmptyPeriod
384	+            ? const ExportJobState.emptyPeriod()
385	+            : ExportJobState.error(failure);
386	+      default:
387	+        // Forward-compatible: an unrecognized `status` (shouldn't happen —
388	+        // the contract's own enum is closed) never crashes the poll loop
389	+        // (RNF09) — surfaces as a terminal error instead.
390	+        return ExportJobState.error(
391	+          Failure.malformedResponse(
392	+            message: 'Unknown export status: $status',
393	+          ),
394	+        );
395	+    }
396	+  }
397	+}
