701	+import 'dart:async';
702	+
703	+import 'package:flutter_bloc/flutter_bloc.dart';
704	+
705	+import '../../domain/entities/export_job_state.dart';
706	+import '../../domain/repositories/export_repository.dart';
707	+
708	+/// Drives `ExportStatusSheet` (spec-7-1) — a fresh, `get_it`-factory-
709	+/// scoped instance per download-icon tap (Code Map: the `registerFactory`
710	+/// one-shot-cubit precedent set by `TextEntryCubit`), closed by the call
711	+/// site itself once done with it (`MeusRegistrosScreen`'s own export handler/
712	+/// `ExportStatusSheet.show()`, mirroring `InsertionModal.show()`'s own
713	+/// cubit-disposal convention), never by a `get_it` `dispose:` hook.
714	+///
715	+/// Starts in [ExportJobState.preparing] — the same visual the
716	+/// `export-summary-create` 202 response's own `status: 'pending'` always
717	+/// implies (`openapi.yaml`), so no separate "creating..." state is needed
718	+/// before [start]'s own `createJob` call resolves.
719	+class ExportJobCubit extends Cubit<ExportJobState> {
720	+  ExportJobCubit(this._repository) : super(const ExportJobState.preparing());
721	+
722	+  final ExportRepository _repository;
723	+
724	+  /// Design Notes — fixed poll cadence (docs/input is silent on this):
725	+  /// the server job always reaches a terminal state, so no client
726	+  /// timeout exists either.
727	+  static const _pollInterval = Duration(seconds: 2);
728	+
729	+  String? _jobId;
730	+  Timer? _pollTimer;
731	+
732	+  /// Creates the export job for [periodStart]/[periodEnd]
733	+  /// (`export-summary-create`) and, on success, starts this cubit's own
734	+  /// `Timer.periodic` poll loop against `export-status-get`.
735	+  ///
736	+  /// Returns `false` on a create failure (Boundaries: "Create fails →
737	+  /// inline error, sheet never opens") — the same failure is also
738	+  /// emitted as [ExportJobState.error] so the caller can read [state] for
739	+  /// [Failure.message] without this method also having to hand back the
740	+  /// raw `Failure` itself (the `Either<Failure, T>` shape, RNF09, is the
741	+  /// repository's own contract, not every cubit method's).
742	+  Future<bool> start({
743	+    required DateTime periodStart,
744	+    required DateTime periodEnd,
745	+  }) async {
746	+    final result = await _repository.createJob(
747	+      periodStart: periodStart,
748	+      periodEnd: periodEnd,
749	+    );
750	+    if (isClosed) {
751	+      return false;
752	+    }
753	+    return result.match(
754	+      (failure) {
755	+        emit(ExportJobState.error(failure));
756	+        return false;
757	+      },
758	+      (jobId) {
759	+        _jobId = jobId;
760	+        _startPolling();
761	+        return true;
762	+      },
763	+    );
764	+  }
765	+
766	+  void _startPolling() {
767	+    _pollTimer?.cancel();
768	+    _pollTimer = Timer.periodic(_pollInterval, (_) => _poll());
769	+  }
770	+
771	+  Future<void> _poll() async {
772	+    final jobId = _jobId;
773	+    if (jobId == null) {
774	+      return;
775	+    }
776	+    final result = await _repository.getStatus(jobId);
777	+    if (isClosed) {
778	+      return;
779	+    }
780	+    result.match(
781	+      (_) {
782	+        // A transient poll failure (docs/input is silent on this) is
783	+        // swallowed rather than surfaced, so one flaky network blip
784	+        // never flips a still-running job to a false terminal error —
785	+        // the next tick simply tries again.
786	+      },
787	+      (newState) {
788	+        emit(newState);
789	+        if (_isTerminal(newState)) {
790	+          _pollTimer?.cancel();
791	+        }
792	+      },
793	+    );
794	+  }
795	+
796	+  bool _isTerminal(ExportJobState state) =>
797	+      state is ExportJobDone ||
798	+      state is ExportJobError ||
799	+      state is ExportJobEmptyPeriod;
800	+
801	+  @override
802	+  Future<void> close() {
803	+    _pollTimer?.cancel();
804	+    return super.close();
805	+  }
806	+}
