1411	+/// A controllable fake (same hand-written convention `ChatCubit`'s own
1412	+/// test suite uses for `ChatRepository`) rather than a mocktail stub —
1413	+/// [getStatusResults] is a queue consumed one entry per `getStatus` call,
1414	+/// repeating its last entry once exhausted, so a test only has to queue
1415	+/// the few stages it cares about.
1416	+class _FakeExportRepository implements ExportRepository {
1417	+  Either<Failure, String> createJobResult = right('job-1');
1418	+  final List<({DateTime periodStart, DateTime periodEnd})> createJobCalls =
1419	+      [];
1420	+
1421	+  final List<Either<Failure, ExportJobState>> getStatusResults = [];
1422	+  final List<String> getStatusCalls = [];
1423	+
1424	+  @override
1425	+  Future<Either<Failure, String>> createJob({
1426	+    required DateTime periodStart,
1427	+    required DateTime periodEnd,
1428	+  }) async {
1429	+    createJobCalls.add((periodStart: periodStart, periodEnd: periodEnd));
1430	+    return createJobResult;
1431	+  }
1432	+
1433	+  @override
1434	+  Future<Either<Failure, ExportJobState>> getStatus(String jobId) async {
1435	+    getStatusCalls.add(jobId);
1436	+    if (getStatusResults.isEmpty) {
1437	+      return right(const ExportJobState.generating());
1438	+    }
1439	+    final index = (getStatusCalls.length - 1).clamp(
1440	+      0,
1441	+      getStatusResults.length - 1,
1442	+    );
1443	+    return getStatusResults[index];
1444	+  }
1445	+}
