213	/// -> cubit.retry(entry.id) -> tracker.retry(tempId)) had no end-to-end
214	/// coverage before; every other link in it was only ever exercised in
215	/// isolation (`entry_record_card_test.dart`, `meus_registros_cubit_test.
216	/// dart`).
217	class _ControllablePendingEntryWriteTracker
218	    implements PendingEntryWriteTracker {
219	  final _pendingController =
220	      StreamController<List<PendingEntryWrite>>.broadcast();
221	  final List<String> retryCalls = [];
222	
223	  void emitPendingWrites(List<PendingEntryWrite> writes) =>
224	      _pendingController.add(writes);
225	
226	  @override
227	  Stream<List<PendingEntryWrite>> get pendingWrites =>
228	      _pendingController.stream;
229	
230	  @override
231	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
232	      const Stream.empty();
233	
234	  @override
235	  Future<Either<Failure, Entry>> create({
236	    required String content,
237	    required EntrySource source,
238	    int? mediaDurationSeconds,
239	  }) async => throw UnimplementedError('not expected to be called');
240	
241	  @override
242	  Future<void> retry(String tempId) async {
243	    retryCalls.add(tempId);
244	  }
245	
246	  @override
247	  Future<void> dispose() async {
248	    await _pendingController.close();
249	  }
250	}
